import {test,expect} from 'bun:test';import {mkdtempSync,rmSync} from 'node:fs';import {tmpdir} from 'node:os';import {join} from 'node:path';import {CoreMindStore,evidenceId} from './core-store';import {CoreMindService} from './core-service';import type{CoreAccess,IngestBatch}from './core-types';
test('source scope withdrawal allows newer authorized observations but an explicit forgotten object remains fenced',()=>{const dir=mkdtempSync(join(tmpdir(),'mind-reauth-')),store=new CoreMindStore(dir),service=new CoreMindService(store);const runtime:CoreAccess={subject:'source',role:'runtime',scopes:[{}]},owner:CoreAccess={subject:'owner',role:'owner',scopes:[{}]};try{const send=(id:string,revision:number,scopeRevision:number,kind:'message'|'retract'='message')=>{const cp=store.read().checkpoints[0];const at=new Date().toISOString();const event:IngestBatch['events'][number]={id,eventId:id,cursor:String(revision),object:{kind:'execution',id:'conversation',revision},kind,actor:'application',origin:{rootId:'conversation'},scope:{sessionId:'conversation'},occurredAt:at,receivedAt:at,scopeRevision,content:{text:id,truncated:false}};service.ingest({sourceIdentity:'chat',epoch:'epoch',expectedCheckpointRevision:cp?.revision??0,scopeRevision,nextCursor:String(revision),capturedAt:at,coverage:{complete:true},events:[event]},runtime);};send('before',1,1);send('withdraw',2,2,'retract');expect(store.read().evidence[0]?.content).toBeUndefined();send('new-authorization',3,3);expect(store.read().evidence.find(e=>e.eventId==='new-authorization')?.content?.text).toBe('new-authorization');service.forget({actionKey:'forget',expectedVisibilityRevision:store.read().visibilityRevision,target:{kind:'evidence',id:evidenceId('chat','epoch','new-authorization')}},owner);send('must-not-return',4,4);expect(store.read().evidence.some(e=>e.eventId==='must-not-return')).toBe(false);}finally{store.close();rmSync(dir,{recursive:true,force:true});}});
